    @Test
    public void testDialectImplementingSeveralFeatures() {

        final TestTextProcessor textProcessor = new TestTextProcessor(TemplateMode.HTML, 10);

        final Map<String, Object> executionAttributes = new LinkedHashMap<String, Object>();
        executionAttributes.put("attribute", "value");

        final TestExpressionObjectFactory expressionObjectFactory = new TestExpressionObjectFactory(
                new LinkedHashSet<String>(Collections.singletonList("object")), true);

        final Set<IPreProcessor> preProcessors = new LinkedHashSet<IPreProcessor>();
        preProcessors.add(new TestPreProcessor(TemplateMode.HTML, 10, TestTemplateHandler.class));

        final TestMultiFeatureDialect dialect = new TestMultiFeatureDialect(
                textProcessor, executionAttributes, expressionObjectFactory, preProcessors);

        final DialectSetConfiguration configuration =
                DialectSetConfiguration.build(configurations(new DialectConfiguration(dialect)));

        assertEquals(Collections.singleton(dialect), configuration.getDialects());
        assertEquals("dialectPrefix", dialect.getRequestedDialectPrefix());
        assertEquals(
                Collections.singletonList(textProcessor),
                unwrapTextProcessors(configuration.getTextProcessors(TemplateMode.HTML)));
        assertEquals("value", configuration.getExecutionAttribute("attribute"));
        assertEquals("objectObject", configuration.getExpressionObjectFactory().buildObject(null, "object"));
        assertEquals(1, configuration.getPreProcessors(TemplateMode.HTML).size());

    }


