package org.thymeleaf.standard.expression;

import java.util.stream.Stream;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.Arguments;
import org.junit.jupiter.params.provider.MethodSource;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertSame;

/**
 * Tests for {@link LiteralSubstitutionUtil#performLiteralSubstitution(String)}.
 *
 * <p>
 *   The tested method rewrites literal substitutions ({@code |...|}) into a concatenation of
 *   literal text (single-quoted, with {@code '} and {@code \} escaped) and standard expressions,
 *   so that the resulting string can be later parsed as a Standard Expression by Thymeleaf.
 * </p>
 */
public final class LiteralSubstitutionUtilPerformLiteralSubstitutionTests {


    @Test
    @DisplayName("null input is returned as null")
    public void testNullInputReturnsNull() {
        assertNull(LiteralSubstitutionUtil.performLiteralSubstitution(null));
    }


    @Test
    @DisplayName("Empty input is returned as the very same (unchanged) instance")
    public void testEmptyInputIsReturnedUnchanged() {
        final String input = "";
        final String output = LiteralSubstitutionUtil.performLiteralSubstitution(input);
        assertEquals("", output);
        assertSame(input, output);
    }


    @Test
    @DisplayName("Inputs without literal substitution delimiters are returned as the very same instance")
    public void testInputWithoutLiteralSubstitutionIsReturnedUnchanged() {
        // When no literal substitution is found, the method does not build any new String at all
        final String[] inputs = new String[] {
                "hello",
                "***",
                "${a}${b}",
                "${a} + 'x'",
                "x${a}y",
                "'a' + ${b}",
                "'literal with | pipe'",       // the pipe is inside a text literal: not a substitution
                "'|a|'",                       // same, at both ends of the text literal
                "'a\\'|b'",                    // text literal with an escaped delimiter, then a pipe
                "|" + "|" + "|" + "|"          // well, this one DOES contain delimiters -> see below
        };
        for (int i = 0; i < inputs.length - 1; i++) {
            assertSame(inputs[i], LiteralSubstitutionUtil.performLiteralSubstitution(inputs[i]));
        }
    }


    @Test
    @DisplayName("Javadoc example: |${onevar} ${twovar}| is converted into an expression concatenation")
    public void testJavadocExample() {
        assertEquals(
                "${onevar} + ' ' + ${twovar}",
                LiteralSubstitutionUtil.performLiteralSubstitution("|${onevar} ${twovar}|"));
    }


    @Test
    @DisplayName("Empty literal substitutions (||) are preserved verbatim")
    public void testEmptyLiteralSubstitutionIsPreserved() {
        assertEquals("||", LiteralSubstitutionUtil.performLiteralSubstitution("||"));
        assertEquals("|||", LiteralSubstitutionUtil.performLiteralSubstitution("|||"));
        assertEquals("||||", LiteralSubstitutionUtil.performLiteralSubstitution("||||"));
        assertEquals("ab||cd", LiteralSubstitutionUtil.performLiteralSubstitution("ab||cd"));
        assertEquals("||${a}||", LiteralSubstitutionUtil.performLiteralSubstitution("||${a}||"));
    }


    @Test
    @DisplayName("A single, unterminated delimiter produces an empty result")
    public void testLoneDelimiterProducesEmptyResult() {
        assertEquals("", LiteralSubstitutionUtil.performLiteralSubstitution("|"));
    }


    @Test
    @DisplayName("Substitution is stateless: interleaved and repeated invocations do not interfere")
    public void testInvocationsAreIndependent() {
        final String firstInput = "|${a} ${b}|";
        final String firstExpected = "${a} + ' ' + ${b}";

        for (int round = 0; round < 3; round++) {
            assertEquals(firstExpected, LiteralSubstitutionUtil.performLiteralSubstitution(firstInput));
            assertEquals("'a'b'c'", LiteralSubstitutionUtil.performLiteralSubstitution("|a|b|c|"));
            assertEquals("${a} + '' + ${b}", LiteralSubstitutionUtil.performLiteralSubstitution("|${a}${b}|"));
            assertEquals("hello", LiteralSubstitutionUtil.performLiteralSubstitution("hello"));
            assertEquals(
                    "'Hello ' + ${name} + '!'",
                    LiteralSubstitutionUtil.performLiteralSubstitution("|Hello ${name}!|"));
        }
    }


    static Stream<Arguments> substitutionCases() {
        return Stream.of(

                // --- literal substitutions containing only expressions ------------------------------
                Arguments.of("|${a}|", "${a}"),
                Arguments.of("|*{sel}|", "*{sel}"),
                Arguments.of("|#{msg}|", "#{msg}"),
                Arguments.of("|@{/url}|", "@{/url}"),
                Arguments.of("|${a}|${b}|", "${a}${b}"),

                // --- literals mixed with expressions -----------------------------------------------
                Arguments.of("|${a} ${b}|", "${a} + ' ' + ${b}"),
                Arguments.of("|Hello ${name}!|", "'Hello ' + ${name} + '!'"),
                Arguments.of("|a${b}c|", "'a' + ${b} + 'c'"),
                Arguments.of("|${a} - ${b}|", "${a} + ' - ' + ${b}"),
                Arguments.of("|${a}[${b}]|", "${a} + '[' + ${b} + ']'"),
                Arguments.of("|${a}.${b}|", "${a} + '.' + ${b}"),
                Arguments.of("| ${a}|", "' ' + ${a}"),
                Arguments.of("|${a} |", "${a} + ' '"),
                Arguments.of("| a |", "' a '"),

                // --- literal substitutions containing no expression at all --------------------------
                Arguments.of("|a|", "'a'"),
                Arguments.of("|$a|", "'$a'"),           // a selector char not followed by '{' is plain text
                Arguments.of("|abc", "'abc"),            // unterminated literal substitution
                Arguments.of("|${a", "${a}"),            // unterminated expression inside a substitution

                // --- text surrounding literal substitutions ----------------------------------------
                Arguments.of("prefix|${a}|suffix", "prefix${a}suffix"),
                Arguments.of("x|${a}|y|${b}|z", "x${a}y${b}z"),
                Arguments.of("a|${b}|c|d|e", "a${b}c'd'e"),
                Arguments.of("|${a}|${b}", "${a}${b}"),
                Arguments.of("${a}|${b}|", "${a}${b}"),
                Arguments.of("|${a}| + 'x'", "${a} + 'x'"),

                // --- concatenation of adjacent expressions inside a substitution -------------------
                Arguments.of("|${a}${b}|", "${a} + '' + ${b}"),
                Arguments.of("|${a}${b}${c}|", "${a} + '' + ${b} + '' + ${c}"),
                Arguments.of("|${a}${b} c|", "${a} + '' + ${b} + ' c'"),
                Arguments.of("x|${a}${b}|y", "x${a} + '' + ${b}y"),

                // --- consecutive / interleaved literal substitutions -------------------------------
                Arguments.of("|a||b|", "'a''b'"),
                Arguments.of("|a|b|c|", "'a'b'c'"),
                Arguments.of("|a| |b|", "'a' 'b'"),
                Arguments.of("|${a}||", "${a}"),

                // --- escaping of text-literal special chars inside substitutions -------------------
                Arguments.of("|a'b|", "'a\\'b'"),
                Arguments.of("|a\\b|", "'a\\\\b'"),
                Arguments.of("|\\|", "'\\\\'"),
                Arguments.of("|\\'a|", "'\\\\\\'a'"),
                Arguments.of("|${a}\\'|", "${a} + '\\\\\\''"),

                // --- braces and multiple-expressions handling --------------------------------------
                Arguments.of("|${a}}|", "${a} + '}'"),
                Arguments.of("|${a}{b}}|", "${a} + '{b}}'"),
                Arguments.of("|${a{b}}|", "${a{b}}"),        // nested braces inside an expression
                Arguments.of("|${'a'}|", "${'a'}"),          // text literal inside an expression
                Arguments.of("|${a=='x|y'}|", "${a=='x|y'}"),// pipe inside an expression is not a delimiter

                // --- line breaks are just literal characters --------------------------------------
                Arguments.of("|${a}\n${b}|", "${a} + '\n' + ${b}")
        );
    }


    @ParameterizedTest(name = "[{index}] \"{0}\" -> \"{1}\"")
    @MethodSource("substitutionCases")
    @DisplayName("Literal substitutions are converted to expression concatenations")
    public void testLiteralSubstitutionConversion(final String input, final String expected) {
        assertEquals(expected, LiteralSubstitutionUtil.performLiteralSubstitution(input));
    }


}
