package org.thymeleaf.templateparser.text;

import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;


public class TextParsingAttributeSequenceUtilParseAttributeSequenceTests {


    @Test
    public void emptyAndWhitespaceOnlySequencesProduceNoAttributes() throws Exception {

        assertTrue(parse("").attributes.isEmpty());
        assertTrue(parse(" \t\n\r\f").attributes.isEmpty());

    }


    @Test
    public void singleAttributeWithoutOperatorOrValueIsReported() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("disabled"));

        assertName(attribute, "disabled", 0, 8, 1, 1);
        assertNoOperator(attribute, 1, 9);
        assertNoValue(attribute, 1, 9);

    }


    @Test
    public void leadingAndTrailingWhitespaceAreExcludedFromUnaryAttribute() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("  disabled  "));

        assertName(attribute, "disabled", 2, 8, 1, 3);
        assertNoOperator(attribute, 1, 11);
        assertNoValue(attribute, 1, 11);

    }


    @Test
    public void unquotedValueHasExpectedRangesAndLocations() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("a=b"));

        assertName(attribute, "a", 0, 1, 1, 1);
        assertOperator(attribute, "=", 1, 1, 1, 2);
        assertValue(attribute, "b", 2, 1, "b", 2, 1, 1, 3);

    }


    @Test
    public void doubleAndSingleQuotedValuesExposeContentWithoutQuotes() throws Exception {

        final RecordingHandler handler = parse("a=\"b\" c='d'");

        assertEquals(2, handler.attributes.size());

        final AttributeCall first = handler.attributes.get(0);
        assertName(first, "a", 0, 1, 1, 1);
        assertOperator(first, "=", 1, 1, 1, 2);
        assertValue(first, "b", 3, 1, "\"b\"", 2, 3, 1, 3);

        final AttributeCall second = handler.attributes.get(1);
        assertName(second, "c", 6, 1, 1, 7);
        assertOperator(second, "=", 7, 1, 1, 8);
        assertValue(second, "d", 9, 1, "'d'", 8, 3, 1, 9);

    }


    @Test
    public void emptyQuotedValueHasZeroLengthContentRange() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("a=\"\""));

        assertName(attribute, "a", 0, 1, 1, 1);
        assertOperator(attribute, "=", 1, 1, 1, 2);
        assertValue(attribute, "", 3, 0, "\"\"", 2, 2, 1, 3);

    }


    @Test
    public void unclosedQuotedValueKeepsQuoteInBothRanges() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("a=\"b"));

        assertName(attribute, "a", 0, 1, 1, 1);
        assertOperator(attribute, "=", 1, 1, 1, 2);
        assertValue(attribute, "\"b", 2, 2, "\"b", 2, 2, 1, 3);

    }


    @Test
    public void whitespaceAroundEqualsSignIsPartOfOperator() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("a = b"));

        assertName(attribute, "a", 0, 1, 1, 1);
        assertOperator(attribute, " = ", 1, 3, 1, 2);
        assertValue(attribute, "b", 4, 1, "b", 4, 1, 1, 5);

    }


    @Test
    public void multipleEqualsSignsArePartOfOperator() throws Exception {

        final AttributeCall compact = onlyAttribute(parse("a==b"));
        assertName(compact, "a", 0, 1, 1, 1);
        assertOperator(compact, "==", 1, 2, 1, 2);
        assertValue(compact, "b", 3, 1, "b", 3, 1, 1, 4);

        final AttributeCall spaced = onlyAttribute(parse("a = = b"));
        assertName(spaced, "a", 0, 1, 1, 1);
        assertOperator(spaced, " = = ", 1, 5, 1, 2);
        assertValue(spaced, "b", 6, 1, "b", 6, 1, 1, 7);

    }


    @Test
    public void adjacentAttributesWithoutEqualsSignAreSeparated() throws Exception {

        final RecordingHandler handler = parse("a b");

        assertEquals(2, handler.attributes.size());

        final AttributeCall first = handler.attributes.get(0);
        assertName(first, "a", 0, 1, 1, 1);
        assertNoOperator(first, 1, 2);
        assertNoValue(first, 1, 2);

        final AttributeCall second = handler.attributes.get(1);
        assertName(second, "b", 2, 1, 1, 3);
        assertNoOperator(second, 1, 4);
        assertNoValue(second, 1, 4);

    }


    @Test
    public void equalsSignWithoutValueProducesOperatorOnlyAttribute() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("a="));
        assertName(attribute, "a", 0, 1, 1, 1);
        assertOperator(attribute, "=", 1, 1, 1, 2);
        assertNoValue(attribute, 1, 3);

        final AttributeCall trailingWhitespace = onlyAttribute(parse("a= "));
        assertName(trailingWhitespace, "a", 0, 1, 1, 1);
        assertOperator(trailingWhitespace, "= ", 1, 2, 1, 2);
        assertNoValue(trailingWhitespace, 1, 4);

    }


    @Test
    public void unquotedValueCanContainAdditionalEqualsSigns() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("a=b=c"));

        assertName(attribute, "a", 0, 1, 1, 1);
        assertOperator(attribute, "=", 1, 1, 1, 2);
        assertValue(attribute, "b=c", 2, 3, "b=c", 2, 3, 1, 3);

    }


    @Test
    public void lineAndColumnAreTrackedAcrossNewlineSeparators() throws Exception {

        final RecordingHandler handler = parse("a=b\nc=d");

        assertEquals(2, handler.attributes.size());

        final AttributeCall first = handler.attributes.get(0);
        assertName(first, "a", 0, 1, 1, 1);
        assertOperator(first, "=", 1, 1, 1, 2);
        assertValue(first, "b", 2, 1, "b", 2, 1, 1, 3);

        final AttributeCall second = handler.attributes.get(1);
        assertName(second, "c", 4, 1, 2, 1);
        assertOperator(second, "=", 5, 1, 2, 2);
        assertValue(second, "d", 6, 1, "d", 6, 1, 2, 3);

    }


    @Test
    public void newlinesInsideQuotedValuesAdvanceLocatorBeforeNextAttribute() throws Exception {

        final RecordingHandler handler = parse("a=\"x\ny\" b=c");

        assertEquals(2, handler.attributes.size());

        final AttributeCall first = handler.attributes.get(0);
        assertName(first, "a", 0, 1, 1, 1);
        assertOperator(first, "=", 1, 1, 1, 2);
        assertValue(first, "x\ny", 3, 3, "\"x\ny\"", 2, 5, 1, 3);

        final AttributeCall second = handler.attributes.get(1);
        assertName(second, "b", 8, 1, 2, 4);
        assertOperator(second, "=", 9, 1, 2, 5);
        assertValue(second, "c", 10, 1, "c", 10, 1, 2, 6);

    }


    @Test
    public void offsetAndLengthRestrictParsingToProvidedWindow() throws Exception {

        final char[] buffer = "xx a=b yy".toCharArray();

        final AttributeCall attribute = onlyAttribute(parse(buffer, 3, 3, 5, 10));
        assertName(attribute, "a", 3, 1, 5, 10);
        assertOperator(attribute, "=", 4, 1, 5, 11);
        assertValue(attribute, "b", 5, 1, "b", 5, 1, 5, 12);

        assertTrue(parse(buffer, 3, 0, 7, 9).attributes.isEmpty());

    }


    @Test
    public void attributeNameMayContainNonOperatorCharacters() throws Exception {

        final AttributeCall attribute = onlyAttribute(parse("data-id=\"x\""));

        assertName(attribute, "data-id", 0, 7, 1, 1);
        assertOperator(attribute, "=", 7, 1, 1, 8);
        assertValue(attribute, "x", 9, 1, "\"x\"", 8, 3, 1, 9);

    }


    @Test
    public void mixedAttributeFormsAreParsedInOneSequence() throws Exception {

        final RecordingHandler handler = parse("first=\"one two\" second third=four");

        assertEquals(3, handler.attributes.size());

        final AttributeCall first = handler.attributes.get(0);
        assertName(first, "first", 0, 5, 1, 1);
        assertOperator(first, "=", 5, 1, 1, 6);
        assertValue(first, "one two", 7, 7, "\"one two\"", 6, 9, 1, 7);

        final AttributeCall second = handler.attributes.get(1);
        assertName(second, "second", 16, 6, 1, 17);
        assertNoOperator(second, 1, 23);
        assertNoValue(second, 1, 23);

        final AttributeCall third = handler.attributes.get(2);
        assertName(third, "third", 23, 5, 1, 24);
        assertOperator(third, "=", 28, 1, 1, 29);
        assertValue(third, "four", 29, 4, "four", 29, 4, 1, 30);

    }


    @Test
    public void attributeNameStartingWithEqualsSignThrowsLocatedException() throws Exception {

        final char[] buffer = " =a".toCharArray();
        final RecordingHandler handler = new RecordingHandler();

        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> TextParsingAttributeSequenceUtil.parseAttributeSequence(
                        buffer, 0, buffer.length, 4, 7, handler));

        assertTrue(handler.attributes.isEmpty());
        assertEquals(Integer.valueOf(4), exception.getLine());
        assertEquals(Integer.valueOf(8), exception.getCol());
        assertEquals(
                "(Line = 4, Column = 8) Bad attribute name in sequence \" =a\": " +
                        "attribute names cannot start with an equals sign",
                exception.getMessage());

    }


    @Test
    public void malformedAttributeAfterValidAttributeReportsPreviousEventBeforeThrowing() throws Exception {

        final char[] buffer = "a= b =c".toCharArray();
        final RecordingHandler handler = new RecordingHandler();

        final TextParseException exception = assertThrows(
                TextParseException.class,
                () -> TextParsingAttributeSequenceUtil.parseAttributeSequence(
                        buffer, 0, buffer.length, 1, 1, handler));

        assertEquals(1, handler.attributes.size());
        final AttributeCall first = handler.attributes.get(0);
        assertName(first, "a", 0, 1, 1, 1);
        assertOperator(first, "= ", 1, 2, 1, 2);
        assertValue(first, "b", 3, 1, "b", 3, 1, 1, 4);

        assertEquals(Integer.valueOf(1), exception.getLine());
        assertEquals(Integer.valueOf(6), exception.getCol());
        assertEquals(
                "(Line = 1, Column = 6) Bad attribute name in sequence \"a= b =c\": " +
                        "attribute names cannot start with an equals sign",
                exception.getMessage());

    }


    private static RecordingHandler parse(final String sequence) throws TextParseException {
        return parse(sequence, 1, 1);
    }


    private static RecordingHandler parse(final String sequence, final int line, final int col)
            throws TextParseException {
        final char[] buffer = sequence.toCharArray();
        return parse(buffer, 0, buffer.length, line, col);
    }


    private static RecordingHandler parse(
            final char[] buffer, final int offset, final int len, final int line, final int col)
            throws TextParseException {

        final RecordingHandler handler = new RecordingHandler();
        TextParsingAttributeSequenceUtil.parseAttributeSequence(buffer, offset, len, line, col, handler);
        return handler;

    }


    private static AttributeCall onlyAttribute(final RecordingHandler handler) {
        assertEquals(1, handler.attributes.size());
        return handler.attributes.get(0);
    }


    private static void assertName(
            final AttributeCall attribute,
            final String expectedName, final int expectedOffset, final int expectedLen,
            final int expectedLine, final int expectedCol) {
        assertEquals(expectedName, attribute.name());
        assertEquals(expectedOffset, attribute.nameOffset);
        assertEquals(expectedLen, attribute.nameLen);
        assertEquals(expectedLine, attribute.nameLine);
        assertEquals(expectedCol, attribute.nameCol);
    }


    private static void assertOperator(
            final AttributeCall attribute,
            final String expectedOperator, final int expectedOffset, final int expectedLen,
            final int expectedLine, final int expectedCol) {
        assertEquals(expectedOperator, attribute.operator());
        assertEquals(expectedOffset, attribute.operatorOffset);
        assertEquals(expectedLen, attribute.operatorLen);
        assertEquals(expectedLine, attribute.operatorLine);
        assertEquals(expectedCol, attribute.operatorCol);
    }


    private static void assertNoOperator(final AttributeCall attribute, final int expectedLine, final int expectedCol) {
        assertOperator(attribute, "", 0, 0, expectedLine, expectedCol);
    }


    private static void assertValue(
            final AttributeCall attribute,
            final String expectedContent, final int expectedContentOffset, final int expectedContentLen,
            final String expectedOuter, final int expectedOuterOffset, final int expectedOuterLen,
            final int expectedLine, final int expectedCol) {
        assertEquals(expectedContent, attribute.valueContent());
        assertEquals(expectedContentOffset, attribute.valueContentOffset);
        assertEquals(expectedContentLen, attribute.valueContentLen);
        assertEquals(expectedOuter, attribute.valueOuter());
        assertEquals(expectedOuterOffset, attribute.valueOuterOffset);
        assertEquals(expectedOuterLen, attribute.valueOuterLen);
        assertEquals(expectedLine, attribute.valueLine);
        assertEquals(expectedCol, attribute.valueCol);
    }


    private static void assertNoValue(final AttributeCall attribute, final int expectedLine, final int expectedCol) {
        assertValue(attribute, "", 0, 0, "", 0, 0, expectedLine, expectedCol);
    }


    private static final class AttributeCall {

        private final char[] buffer;
        private final int nameOffset;
        private final int nameLen;
        private final int nameLine;
        private final int nameCol;
        private final int operatorOffset;
        private final int operatorLen;
        private final int operatorLine;
        private final int operatorCol;
        private final int valueContentOffset;
        private final int valueContentLen;
        private final int valueOuterOffset;
        private final int valueOuterLen;
        private final int valueLine;
        private final int valueCol;

        private AttributeCall(
                final char[] buffer,
                final int nameOffset, final int nameLen,
                final int nameLine, final int nameCol,
                final int operatorOffset, final int operatorLen,
                final int operatorLine, final int operatorCol,
                final int valueContentOffset, final int valueContentLen,
                final int valueOuterOffset, final int valueOuterLen,
                final int valueLine, final int valueCol) {
            this.buffer = buffer;
            this.nameOffset = nameOffset;
            this.nameLen = nameLen;
            this.nameLine = nameLine;
            this.nameCol = nameCol;
            this.operatorOffset = operatorOffset;
            this.operatorLen = operatorLen;
            this.operatorLine = operatorLine;
            this.operatorCol = operatorCol;
            this.valueContentOffset = valueContentOffset;
            this.valueContentLen = valueContentLen;
            this.valueOuterOffset = valueOuterOffset;
            this.valueOuterLen = valueOuterLen;
            this.valueLine = valueLine;
            this.valueCol = valueCol;
        }

        private String name() {
            return new String(this.buffer, this.nameOffset, this.nameLen);
        }

        private String operator() {
            return new String(this.buffer, this.operatorOffset, this.operatorLen);
        }

        private String valueContent() {
            return new String(this.buffer, this.valueContentOffset, this.valueContentLen);
        }

        private String valueOuter() {
            return new String(this.buffer, this.valueOuterOffset, this.valueOuterLen);
        }

    }


    private static final class RecordingHandler implements ITextHandler {

        private final List<AttributeCall> attributes = new ArrayList<AttributeCall>();

        @Override
        public void handleDocumentStart(final long startTimeNanos, final int line, final int col) {
            throw new AssertionError("handleDocumentStart should not be called");
        }

        @Override
        public void handleDocumentEnd(
                final long endTimeNanos, final long totalTimeNanos, final int line, final int col) {
            throw new AssertionError("handleDocumentEnd should not be called");
        }

        @Override
        public void handleText(
                final char[] buffer, final int offset, final int len, final int line, final int col) {
            throw new AssertionError("handleText should not be called");
        }

        @Override
        public void handleComment(
                final char[] buffer,
                final int contentOffset, final int contentLen,
                final int outerOffset, final int outerLen,
                final int line, final int col) {
            throw new AssertionError("handleComment should not be called");
        }

        @Override
        public void handleStandaloneElementStart(
                final char[] buffer, final int nameOffset, final int nameLen,
                final boolean minimized, final int line, final int col) {
            throw new AssertionError("handleStandaloneElementStart should not be called");
        }

        @Override
        public void handleStandaloneElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen,
                final boolean minimized, final int line, final int col) {
            throw new AssertionError("handleStandaloneElementEnd should not be called");
        }

        @Override
        public void handleOpenElementStart(
                final char[] buffer, final int nameOffset, final int nameLen,
                final int line, final int col) {
            throw new AssertionError("handleOpenElementStart should not be called");
        }

        @Override
        public void handleOpenElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen,
                final int line, final int col) {
            throw new AssertionError("handleOpenElementEnd should not be called");
        }

        @Override
        public void handleCloseElementStart(
                final char[] buffer, final int nameOffset, final int nameLen,
                final int line, final int col) {
            throw new AssertionError("handleCloseElementStart should not be called");
        }

        @Override
        public void handleCloseElementEnd(
                final char[] buffer, final int nameOffset, final int nameLen,
                final int line, final int col) {
            throw new AssertionError("handleCloseElementEnd should not be called");
        }

        @Override
        public void handleAttribute(
                final char[] buffer,
                final int nameOffset, final int nameLen,
                final int nameLine, final int nameCol,
                final int operatorOffset, final int operatorLen,
                final int operatorLine, final int operatorCol,
                final int valueContentOffset, final int valueContentLen,
                final int valueOuterOffset, final int valueOuterLen,
                final int valueLine, final int valueCol) {
            this.attributes.add(new AttributeCall(
                    buffer,
                    nameOffset, nameLen, nameLine, nameCol,
                    operatorOffset, operatorLen, operatorLine, operatorCol,
                    valueContentOffset, valueContentLen, valueOuterOffset, valueOuterLen,
                    valueLine, valueCol));
        }

    }


}
